/// Complete and official Bangladesh Unions & Pourashavas Dataset
/// Contains all 495 Upazilas, Metropolitan Police Thanas, Union Parishads, and Pourashavas.
/// Loaded instantly (0ms) offline without any API dependency.
class BangladeshUnionsData {
  /// Normalize Bengali characters (reph, nukta, composite vs decomposed)
  static String normalizeBn(String input) {
    return input
        .replaceAll('\u09b0\u09bc', '\u09dc') // র + nukta -> ড়
        .replaceAll('\u09a2\u09bc', '\u09dd') // ঢ + nukta -> ঢ়
        .replaceAll('\u09af\u09bc', '\u09df') // য + nukta -> য়
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

