  /// Check if a given string represents a Pourashava / Municipality
  static bool isPourashava(String? name) {
    if (name == null || name.trim().isEmpty) return false;
    final norm = normalizeBn(name.trim().toLowerCase());
    if (norm == 'পৌরসভা' ||
        norm.contains('পৌরসভা') ||
        norm.contains('pouro') ||
        norm.contains('municipality') ||
        norm.contains('সিটি কর্পোরেশন')) {
      return true;
    }
    return allPourashavas.contains(name.trim()) || allPourashavas.contains(norm);
  }

  /// Get official Pourashavas for a given Upazila
  static List<String> getPourashavas(String upazilaName) {
    final clean = normalizeBn(upazilaName.trim());
    if (upazilaToPourashavas.containsKey(clean)) {
      return upazilaToPourashavas[clean]!;
    }
    final lower = clean.toLowerCase();
    if (upazilaToPourashavas.containsKey(lower)) {
      return upazilaToPourashavas[lower]!;
    }
    return [];
  }

  /// Get all Unions and Pourashavas for a given Upazila instantly (0ms)
  static List<String> getUnions(String upazilaName) {
    final clean = normalizeBn(upazilaName.trim());
    if (clean.isEmpty) return [];

    List<String> raw = [];
    if (upazilaToUnions.containsKey(clean)) {
      raw = upazilaToUnions[clean]!;
    } else if (upazilaToUnions.containsKey(clean.toLowerCase())) {
      raw = upazilaToUnions[clean.toLowerCase()]!;
    } else {
      // Substring fallback
      for (var entry in upazilaToUnions.entries) {
        final keyNorm = normalizeBn(entry.key);
        if (keyNorm.length >= 3 && (keyNorm.contains(clean) || clean.contains(keyNorm))) {
          raw = entry.value;
          break;
        }
      }
    }

    if (raw.isNotEmpty) {
      return raw;
    }

    // Default fallback for wards in metro thanas
    return const [
      'ওয়ার্ড ১',
      'ওয়ার্ড ২',
      'ওয়ার্ড ৩',
      'ওয়ার্ড ৪',
      'ওয়ার্ড ৫',
      'ওয়ার্ড ৬',
      'ওয়ার্ড ৭',
      'ওয়ার্ড ৮',
      'ওয়ার্ড ৯',
    ];
  }
